patch:
diff --git a/recreate/check-use-strict.js b/recreate/check-use-strict.js
new file mode 100644
index 0000000..c1b0d99
--- /dev/null
+++ b/recreate/check-use-strict.js
@@ -0,0 +1,47 @@
+"use strict";
+
+/*
+ * Check for "no-unused-expressions started to trigger on 'use strict' in 9.25.0".
+ * Expected: a 'use strict' directive is not reported by no-unused-expressions.
+ * Exits non-zero while the bug is present, zero once it is fixed.
+ * ESLINT_API can point at another ESLint install (default: this checkout).
+ */
+
+const { ESLint } = require(process.env.ESLINT_API || "../lib/api");
+
+(async () => {
+	const eslint = new ESLint({
+		overrideConfigFile: true,
+		overrideConfig: [
+			{
+				// the core-js config lints packages/core-js with ecmaVersion 3
+				languageOptions: { ecmaVersion: 3, sourceType: "script" },
+				rules: { "no-unused-expressions": "error" },
+			},
+		],
+	});
+
+	const [result] = await eslint.lintText("'use strict';\nfoo();\n", {
+		filePath: "a.js",
+	});
+
+	const fatal = result.messages.filter(m => m.fatal);
+
+	if (fatal.length) {
+		console.error("setup error:", fatal);
+		process.exit(2);
+	}
+
+	const unexpected = result.messages.filter(
+		m => m.ruleId === "no-unused-expressions",
+	);
+
+	for (const m of unexpected) {
+		console.error(`FAIL ${m.line}:${m.column} ${m.message} (${m.ruleId})`);
+	}
+
+	if (unexpected.length) {
+		process.exit(1);
+	}
+	console.log("OK: no-unused-expressions does not report 'use strict'");
+})();
